import re


def rule_individual_income_tax_receipts(doc: dict) -> list[dict]:
    try:
        results = []
        seen = set()

        patterns = [
            re.compile(r"individual income tax receipts(?:, net of refunds)?(?:,)? were \$[\d,]+(?:\.\d+)?", re.I),
            re.compile(r"individual income taxes.*?receipts, net of refunds, were \$[\d,]+(?:\.\d+)?", re.I),
            re.compile(r"individual income taxes.*?individual income tax receipts.*?were \$[\d,]+(?:\.\d+)?", re.I),
        ]

        def add_span(text, extra=None):
            if not text:
                return
            norm_text = " ".join(str(text).split())
            key = (norm_text, tuple(sorted(extra.items())) if extra else ())
            if key in seen:
                return
            seen.add(key)
            span = {"text": norm_text}
            if extra:
                span.update(extra)
            results.append(span)

        for paragraph in doc.get("paragraphs", []) or []:
            text = paragraph.get("text", "") or ""
            if "individual income tax" not in text.lower():
                continue
            if not any(p.search(text.replace("\n", " ")) for p in patterns):
                continue
            add_span(
                text,
                {
                    "page_no": paragraph.get("page_no"),
                    "paragraph_no": paragraph.get("paragraph_no"),
                },
            )

        if results:
            return results

        for line in doc.get("lines", []) or []:
            text = line.get("text", "") or ""
            if "individual income tax" not in text.lower():
                continue
            if not any(p.search(text.replace("\n", " ")) for p in patterns):
                continue
            add_span(
                text,
                {
                    "page_no": line.get("page_no"),
                    "line_no": line.get("line_no"),
                },
            )

        if results:
            return results

        text = doc.get("text", "") or ""
        low = text.lower()
        if "individual income tax" in low and "$" in text:
            for pat in patterns:
                m = pat.search(text.replace("\n", " "))
                if m:
                    add_span(m.group(0))
                    break
            if results:
                return results

        table_anchors = [
            "net budget receipts, by source",
            "table ffo-2",
            "on-budget and off-budget receipts by source",
            "onbudget and off-budget receipts by source",
            "budget receipts by source",
            "receipts by source",
            "budget receipts by",
        ]
        if any(anchor in low for anchor in table_anchors) and (
            "individual" in low or "income taxes" in low or "withheld" in low or "refunds" in low
        ):
            for anchor in table_anchors:
                idx = low.find(anchor)
                if idx == -1:
                    continue
                start = max(0, idx - 250)
                end = min(len(text), idx + 3500)
                window = " ".join(text[start:end].split())
                if window:
                    add_span(window)
                    break

        return results
    except Exception:
        return []

import re


def rule_individual_income_tax_receipts_quarter(doc: dict) -> list[dict]:
    try:
        paragraphs = doc.get("paragraphs") or []
        text = doc.get("text") or ""

        def norm(value: str) -> str:
            return re.sub(r"\s+", " ", (value or "")).strip().lower()

        def make_span(item: dict, answer: str) -> dict:
            span = {"text": answer}
            if item.get("page_no") is not None:
                span["page_no"] = item.get("page_no")
            if item.get("paragraph_no") is not None:
                span["paragraph_no"] = item.get("paragraph_no")
            if item.get("line_no") is not None:
                span["line_no"] = item.get("line_no")
            return span

        patterns = [
            re.compile(
                r"individual income tax receipts(?:\s*,?\s*net of refunds,?)?\s*were\s*\$?([0-9][0-9,]*(?:\.[0-9]+)?)\s*billion",
                re.I,
            ),
            re.compile(
                r"individual income taxes[—-]\s*individual income tax receipts(?:\s*,?\s*net of refunds,?)?\s*were\s*\$?([0-9][0-9,]*(?:\.[0-9]+)?)\s*billion",
                re.I,
            ),
        ]

        for paragraph in paragraphs:
            ptext = paragraph.get("text") or ""
            low = norm(ptext)
            if "individual income tax" not in low or "receipt" not in low:
                continue
            for pat in patterns:
                m = pat.search(low)
                if m:
                    return [make_span(paragraph, m.group(1))]

        low_text = norm(text)
        if "individual income tax" in low_text and "receipt" in low_text:
            for pat in patterns:
                m = pat.search(low_text)
                if m:
                    return [make_span({}, m.group(1))]

        return []
    except Exception:
        return []

