in low:\n                continue\n            for pattern in sentence_patterns:\n                match = pattern.search(clean)\n                if match:\n                    add_span(\n                        match.group(0),\n                        {\n                            \"page_no\": paragraph.get(\"page_no\"),\n                            \"paragraph_no\": paragraph.get(\"paragraph_no\"),\n                        },\n                    )\n                    break\n\n        if results:\n            return results\n\n        lines = doc.get(\"lines\", []) or []\n        for idx, line in enumerate(lines):\n            window_lines = lines[max(0, idx - 1) : min(len(lines), idx + 4)]\n            joined = norm(\" \".join((item.get(\"text\", \"\") or \"\") for item in window_lines))\n            if \"individual income tax\" not in joined.lower():\n                continue\n            for pattern in sentence_patterns:\n                match = pattern.search(joined)\n                if match:\n                    add_span(\n                        match.group(0),\n                        {\n                            \"page_no\": line.get(\"page_no\"),\n                            \"line_no\": line.get(\"line_no\"),\n                        },\n                    )\n                    break\n\n        if results:\n            return results\n\n        text = doc.get(\"text\", \"\") or \"\"\n        clean_text = norm(text)\n        low_text = clean_text.lower()\n\n        if \"individual income tax\" in low_text:\n            for pattern in sentence_patterns:\n                match = pattern.search(clean_text)\n                if match:\n                    add_span(match.group(0))\n                    break\n\n        if results:\n            return results\n\n        table_title_patterns = [\n            re.compile(\n                r\"(?:first|second|third|fourth).{0,40}(?:quarter|ouart(?:er|cr)).{0,180}(?:source|sourca)\",\n                re.I,\n            ),\n            re.compile(r\"(?:net|nat).{0,20}budg.{0,20}(?:receipts?|racalpta).{0,30}(?:source|sourca)\", re.I),\n            re.compile(r\"table\\s+ffo-2\", re.I),\n        ]\n\n        first_individual = None\n        for probe in (\"individual income taxes\", \"individual income tax receipts\", \"individual income\"):\n            pos = low_text.find(probe)\n            if pos != -1:\n                first_individual = pos\n                break\n\n        if first_individual is not None:\n            for pattern in table_title_patterns:\n                for match in pattern.finditer(clean_text):\n                    start = max(0, match.start() - 120)\n                    end = min(len(clean_text), match.end() + 2200)\n                    window = clean_text[start:end]\n                    if \"individual income\" in window.lower():\n                        add_span(window)\n                        break\n                if results:\n                    break\n\n        if not results and first_individual is not None:\n            start = max(0, first_individual - 350)\n            end = min(len(clean_text), first_individual + 2200)\n            window = clean_text[start:end]\n            if any(token in window.lower() for token in (\"quarter\", \"ouart\", \"budget\", \"budgat\", \"[in billions\", \"source\")):\n                add_span(window)\n\n        return results\n    except Exception:\n        return []\n",
